(1965697, 270544, 10413, '<td valign="top">Nice one. My husband loved this.</td>', 'Nice one. My husband loved this.', '2005-12-20 19:23:16.000000', NULL, 1),
(1965699, 270301, 10413, '<td valign="top">Clever one and nice DOF</td>', 'Clever one and nice DOF', '2005-12-20 19:23:42.000000', NULL, 1),
(1965701, 269981, 47852, '<td valign="top">The white is just a bit too bright, and I might have found a way to get rid of the shadow of the table legs.  Good pun and creatively done!</td>', 'The white is just a bit too bright, and I might have found a way to get rid of the shadow of the table legs.  Good pun and creatively done!', '2005-12-20 19:24:48.000000', NULL, 1),
(1965704, 270444, 10413, '<td valign="top">Nice crisp shot. Beautiful sword. I hate snakes though. Didn''t mark you down for the snake. :)</td>', 'Nice crisp shot. Beautiful sword. I hate snakes though. Didn''t mark you down for the snake. :)', '2005-12-20 19:26:00.000000', NULL, 1),
(1965705, 268651, 10413, '<td valign="top">Unique and clever idea.</td>', 'Unique and clever idea.', '2005-12-20 19:26:32.000000', NULL, 1),
(1965708, 269961, 47852, '<td valign="top">Before reading the title, I was trying to figure out what an icy lens was since it looked like ice frozen in the lens.  Very creative and well done!</td>', 'Before reading the title, I was trying to figure out what an icy lens was since it looked like ice frozen in the lens.  Very creative and well done!', '2005-12-20 19:27:04.000000', NULL, 1),
(1965711, 270413, 10413, '<td valign="top">Great title and idea. Made me smile.</td>', 'Great title and idea. Made me smile.', '2005-12-20 19:28:26.000000', NULL, 1),
(1965712, 270187, 47852, '<td valign="top">Poor kitty :(  I love the expression on his face too... almost as if to say "I''m gonna get you for this!"  Great pun!</td>', 'Poor kitty :(  I love the expression on his face too... almost as if to say "I''m gonna get you for this!"  Great pun!', '2005-12-20 19:28:30.000000', NULL, 1),
