(1966310, 270604, 1, '<td valign="top">Nice, great humor.  Love the position of the camera too.</td>', 'Nice, great humor.  Love the position of the camera too.', '2005-12-21 00:15:24.000000', NULL, 1),
(1966650, 270590, 49865, '<td valign="top">Nice xmas theme on this one</td>', 'Nice xmas theme on this one', '2005-12-21 01:30:45.000000', NULL, 1),
(1966658, 270671, 44287, '<td valign="top">This is one of the most original photographs. Very clever idea, and excellent contrast against the black.</td>', 'This is one of the most original photographs. Very clever idea, and excellent contrast against the black.', '2005-12-21 01:33:13.000000', NULL, 1),
(1966781, 270654, 39243, '<td valign="top">My guess is that most people on this site will not understand the reference to the colts losing (13-1 now). I however think this is extreemly apropo! All of the Colts look like they are fans and the Chargers look like they are in the middle of something good! Well shot. 8</td>', 'My guess is that most people on this site will not understand the reference to the colts losing (13-1 now). I however think this is extreemly apropo! All of the Colts look like they are fans and the Chargers look like they are in the middle of something good! Well shot. 8', '2005-12-21 01:59:11.000000', NULL, 1),
(1966789, 269040, 39243, '<td valign="top">Awesome! 9</td>', 'Awesome! 9', '2005-12-21 02:00:38.000000', NULL, 1),
